/** report-1 document construction. */
import os from 'node:os';
import path from 'node:path';
import { ENGINE_SPI_VERSION } from '../engine/contract.js';
import { BLOCKABLE_CODES } from '../agent/executor.js';
import { DEFAULT_LIMITS } from '../config/agent.js';
import { resultId, timestamp } from '../internal/ids.js';
import { obj } from '../internal/objects.js';
import { packageVersion } from '../internal/package-version.js';
import { onBun } from '../internal/runtime.js';
import { projectRelativePath } from '../internal/source.js';
import { expectedFailureOf, memberRan, someSkippedAfterFailure } from '../run/records.js';
/**
 * What a target's engine declaration says about it: the one description the
 * runner grades against and the report records. A target without an engine is
 * agent-tools-only and honestly reports no capabilities.
 */
export function describeTarget(target) {
    const engine = target.engine;
    const artifactCapabilities = [];
    if (engine?.artifacts !== undefined) {
        artifactCapabilities.push('screenshot');
        if (engine.artifacts.startVideo !== undefined)
            artifactCapabilities.push('video');
    }
    return {
        engine: {
            name: engine?.name ?? 'none',
            version: engine?.version ?? 'unversioned',
            spiVersion: engine?.spiVersion ?? ENGINE_SPI_VERSION,
        },
        capabilities: [...(engine?.capabilities ?? [])].toSorted(),
        artifactCapabilities,
        stateCapability: engine?.state !== undefined,
    };
}
function relativeSource(config, source, fallbackFile) {
    return projectSource(config?.projectRoot, source, fallbackFile) ?? { file: fallbackFile, line: 1, column: 1 };
}
/**
 * A recorded declaration as the report writes it: project-relative, line and
 * column at least 1. A file outside the project becomes `fallbackFile`; no
 * recorded source stays `undefined`.
 */
export function projectSource(projectRoot, source, fallbackFile) {
    if (source === undefined)
        return undefined;
    let file = source.file;
    if (projectRoot !== undefined && path.isAbsolute(file)) {
        file = projectRelativePath(projectRoot, file) ?? fallbackFile;
    }
    if (file.startsWith('/') || /^[A-Za-z]:/.test(file)) {
        file = fallbackFile;
    }
    return { file, line: Math.max(1, source.line), column: Math.max(1, source.column) };
}
/** A step that named no line in the project: a fixture's own call, or a step minted outside one. */
const UNKNOWN_STEP_SOURCE = { file: 'unknown', line: 1, column: 1 };
function serializeStep(step) {
    const { error, source, ...rest } = step;
    return {
        ...rest,
        source: source ?? UNKNOWN_STEP_SOURCE,
        error: error === undefined ? undefined : serializeErrorRecord(error),
    };
}
/** SerializedError minus the stack, which never enters the report. */
function serializeErrorRecord(error) {
    const { stack, ...report } = error;
    void stack;
    return report;
}
function serializeAttemptBase(attempt) {
    return {
        id: attempt.id,
        index: attempt.index,
        status: attempt.status,
        startedAt: attempt.startedAt,
        durationMs: attempt.durationMs,
        artifacts: attempt.artifacts,
        error: attempt.error === undefined ? undefined : serializeErrorRecord(attempt.error),
        secondaryErrors: attempt.secondaryErrors.map(serializeErrorRecord),
        cleanup: attempt.cleanup,
        ...(attempt.environment === undefined ? {} : { environment: attempt.environment }),
    };
}
function serializeAttempt(attempt) {
    return {
        ...serializeAttemptBase(attempt),
        ...(attempt.failure === undefined ? {} : { failure: attempt.failure }),
        ...(attempt.skip === undefined ? {} : { skip: attempt.skip }),
        ...(attempt.expectedFailure === undefined
            ? {}
            : {
                expectedFailure: {
                    reason: attempt.expectedFailure.reason,
                    ...(attempt.expectedFailure.error === undefined ? {} : { error: serializeErrorRecord(attempt.expectedFailure.error) }),
                },
            }),
        steps: attempt.steps.map(serializeStep),
        ...(attempt.appLog === undefined ? {} : { appLog: attempt.appLog }),
    };
}
function serializeSerialMember(member) {
    return {
        id: member.id,
        index: member.index,
        testId: member.testId,
        status: member.status,
        startedAt: member.startedAt,
        durationMs: member.durationMs,
        // A member skipped at selection has no steps; one that skipped itself keeps the steps that ran.
        steps: member.steps.map(serializeStep),
        ...(member.appLog === undefined ? {} : { appLog: member.appLog }),
        error: member.error === undefined ? undefined : serializeErrorRecord(member.error),
        ...(member.failure === undefined ? {} : { failure: member.failure }),
        ...(member.skip === undefined ? {} : { skip: member.skip }),
        secondaryErrors: member.secondaryErrors.map(serializeErrorRecord),
    };
}
function serializeSerialAttempt(attempt) {
    return {
        ...serializeAttemptBase(attempt),
        status: attempt.status,
        cutRetry: attempt.cutRetry,
        members: attempt.members.map(serializeSerialMember),
    };
}
function serializeSerialGroup(group) {
    return {
        id: group.id,
        serialId: group.serialId,
        declarationIndex: group.declarationIndex,
        file: group.file,
        source: { file: group.file, line: 1, column: 1 },
        titlePath: group.titlePath,
        targetId: group.targetId,
        platform: group.platform,
        agent: group.agent,
        repeat: group.repeat,
        memberTestIds: group.memberTestIds,
        status: group.status,
        skip: group.status === 'skipped' ? group.skip : undefined,
        attempts: group.attempts.map(serializeSerialAttempt),
    };
}
function serializeResult(config, result) {
    return {
        id: resultId(result.test.id, result.target.name, result.agent, result.repeat),
        testId: result.test.id,
        kind: result.test.kind,
        declarationIndex: result.test.declarationIndex,
        titlePath: result.test.titlePath,
        file: result.test.file,
        source: relativeSource(config, result.test.source, result.test.file),
        targetId: result.target.name,
        platform: result.target.platform,
        agent: result.agent,
        repeat: result.repeat,
        tags: result.test.tags,
        selected: result.selected,
        serialGroupId: result.serialGroupId,
        status: result.status,
        skip: result.status === 'skipped' ? result.skip : undefined,
        ...expectedFailureField(result),
        attempts: result.serialGroupId !== undefined ? [] : result.attempts.map(serializeAttempt),
    };
}
/** The result's `expectedFailure` field, from its last attempt's mark. */
function expectedFailureField(result) {
    const mark = expectedFailureOf(result);
    return mark === undefined ? {} : { expectedFailure: { reason: mark.reason } };
}
function serializeTarget(config, target, provenance) {
    // Provenance exists for every selected target; an unselected one is
    // described from its declaration the same way.
    return {
        ...obj({
            id: target.name,
            index: target.index,
            platform: target.platform,
            baseOrigin: target.app.base?.origin,
            environment: target.app.environment,
        }),
        ...(provenance ?? describeTarget(target)),
    };
}
/**
 * Computes report-1 summary counts from results; the status counts are over
 * the selected ones. A result executed when it made an attempt; a serial
 * member's attempts are its records in its group's attempts.
 */
function computeSummary(results, serialGroups) {
    const ranMembers = new Set(serialGroups.flatMap((group) => group.attempts.flatMap((attempt) => attempt.members.filter(memberRan).map((member) => `${group.id}\u0000${member.testId}`))));
    let selected = 0;
    let executed = 0;
    let passed = 0;
    let failed = 0;
    let interrupted = 0;
    let flaky = 0;
    let skipped = 0;
    for (const result of results) {
        if (result.attempts.length > 0 || (result.serialGroupId !== undefined && ranMembers.has(`${result.serialGroupId}\u0000${result.test.id}`))) {
            executed += 1;
        }
        if (!result.selected)
            continue;
        selected += 1;
        switch (result.status) {
            case 'passed':
                passed += 1;
                break;
            case 'flaky':
                flaky += 1;
                break;
            case 'failed':
            case 'timed-out':
                failed += 1;
                break;
            case 'interrupted':
                interrupted += 1;
                break;
            case 'skipped':
                skipped += 1;
                break;
        }
    }
    return { discovered: results.length, selected, executed, passed, failed, interrupted, flaky, skipped };
}
/**
 * A run is `blocked` — not failed — when it did not pass and *every*
 * non-passing result carries a blockable error code: credentials, the
 * environment, or the agent's own budget prevented a product verdict, and
 * nothing contradicts that. One genuine failure keeps the run failed, and so
 * does any run-level error (a launch that never came up, a cleanup or report
 * write that failed): it is its own fact about the run, not a blocked step,
 * and it must stay visible to a host reading the status. So does a skip after
 * a failure under `failOnSkippedFailure`. Derivation requires
 * positive evidence, never absence of it.
 */
function deriveRunStatus(status, results, serialGroups, runErrors, failOnSkippedFailure) {
    if (status !== 'failed' && status !== 'error')
        return status;
    if (runErrors.length > 0)
        return status;
    if (failOnSkippedFailure && someSkippedAfterFailure(results, serialGroups))
        return status;
    // Serial members carry no attempts of their own; their failing error lives
    // on the group's last attempt (or its failing member).
    const groupCode = new Map();
    for (const group of serialGroups) {
        const attempt = group.attempts.at(-1);
        const member = attempt?.members.find((candidate) => candidate.status !== 'passed' && candidate.status !== 'skipped');
        groupCode.set(group.id, member?.error?.code ?? attempt?.error?.code);
    }
    let sawFailure = false;
    for (const result of results) {
        if (result.status !== 'failed' &&
            result.status !== 'timed-out' &&
            result.status !== 'interrupted') {
            continue;
        }
        sawFailure = true;
        const code = result.serialGroupId === undefined
            ? result.attempts.at(-1)?.error?.code
            : groupCode.get(result.serialGroupId);
        if (code === undefined || !BLOCKABLE_CODES.has(code))
            return status;
    }
    return sawFailure ? 'blocked' : status;
}
/** Aggregates observed usage against the resolved limits. */
function computeUsage(options) {
    const usage = {
        discoveredResults: options.discovered,
        maxAgentContextBytes: 0,
        maxLedgerBytes: 0,
        maxObservationBytes: 0,
        artifactBytes: 0,
        downloads: 0,
        events: 0,
        modelTokens: 0,
        maxModelCallsInStep: 0,
        maxActionStepsInStep: 0,
    };
    let cost = 0;
    let costSeen = false;
    let cachedTokens;
    const countStep = (step) => {
        usage.events += step.events.length;
        const metrics = step.metrics;
        if (metrics !== undefined) {
            usage.maxAgentContextBytes = Math.max(usage.maxAgentContextBytes, metrics.contextBytes);
            usage.maxLedgerBytes = Math.max(usage.maxLedgerBytes, metrics.ledgerBytes);
            usage.maxObservationBytes = Math.max(usage.maxObservationBytes, metrics.observationBytes);
            usage.maxModelCallsInStep = Math.max(usage.maxModelCallsInStep, metrics.modelCalls);
            usage.maxActionStepsInStep = Math.max(usage.maxActionStepsInStep, metrics.actionSteps);
        }
        const model = step.model;
        if (model !== undefined) {
            usage.modelTokens = Math.min(Number.MAX_SAFE_INTEGER, usage.modelTokens + model.inputTokens + model.outputTokens);
            if (model.cacheReadTokens !== undefined) {
                cachedTokens = Math.min(Number.MAX_SAFE_INTEGER, (cachedTokens ?? 0) + model.cacheReadTokens);
            }
            if (model.estimatedCostUsd !== undefined) {
                cost += model.estimatedCostUsd;
                costSeen = true;
            }
        }
    };
    const countArtifacts = (artifacts) => {
        for (const artifact of artifacts) {
            usage.artifactBytes += artifact.size ?? 0;
            if (artifact.kind === 'download')
                usage.downloads += 1;
        }
    };
    for (const result of options.results) {
        for (const attempt of result.attempts) {
            countArtifacts(attempt.artifacts);
            for (const step of attempt.steps)
                countStep(step);
        }
    }
    for (const group of options.serialGroups) {
        for (const attempt of group.attempts) {
            countArtifacts(attempt.artifacts);
            for (const member of attempt.members) {
                for (const step of member.steps)
                    countStep(step);
            }
        }
    }
    return {
        ...usage,
        ...(cachedTokens === undefined ? {} : { modelCachedTokens: cachedTokens }),
        ...(costSeen && Number.isFinite(cost) ? { estimatedCostUsd: cost } : {}),
    };
}
/** Builds the complete report-1 document. */
export function buildReport(options) {
    const { config } = options;
    const targets = config === undefined
        ? []
        : config.targets.map((target) => serializeTarget(config, target, options.targetProvenance.get(target.name)));
    const results = options.results
        .toSorted(compareResults)
        .map((result) => serializeResult(config, result));
    const targetIndex = new Map();
    for (const target of config?.targets ?? [])
        targetIndex.set(target.name, target.index);
    const serialGroups = options.serialGroups
        .toSorted((a, b) => compareSerialGroups(a, b, targetIndex))
        .map(serializeSerialGroup);
    const summary = computeSummary(options.results, options.serialGroups);
    return {
        schemaVersion: 'report-1',
        run: {
            id: options.runId,
            specVersion: '0.1',
            runner: {
                name: 'e2e',
                version: packageVersion(import.meta.url, '../../package.json', '0.0.0'),
            },
            status: deriveRunStatus(options.status, options.results, options.serialGroups, options.runErrors, config?.failOnSkippedFailure === true),
            exitCode: options.exitCode,
            startedAt: options.startedAt,
            finishedAt: timestamp(),
            project: {
                id: config?.projectId ?? 'unknown',
                configDigest: config?.configDigest ?? '0'.repeat(64),
            },
            environment: {
                ci: config?.ci ?? false,
                // The trust model is documented and report-recorded, never printed.
                trustNoticeShown: false,
                os: `${os.platform()} ${os.release()}`,
                arch: os.arch(),
                runtime: onBun ? `bun v${process.versions['bun']}` : `node ${process.version}`,
            },
            ...(options.vcs === undefined ? {} : { vcs: options.vcs }),
            targets,
            serialGroups,
            results,
            errors: options.runErrors.map((runError) => serializeErrorRecord(runError.error)),
            summary,
            limits: config?.limits ?? DEFAULT_LIMITS,
            usage: computeUsage({
                results: options.results,
                serialGroups: options.serialGroups,
                discovered: summary.discovered,
            }),
            ...(options.changes === undefined ? {} : { changes: options.changes }),
            ...(options.filters === undefined || options.filters.length === 0 ? {} : { filters: options.filters }),
            ...(options.explore === undefined ? {} : { explore: options.explore }),
        },
    };
}
/** Report order of two tests: by file, then by declaration within it. */
export function compareTests(a, b) {
    if (a.file !== b.file)
        return a.file < b.file ? -1 : 1;
    return a.declarationIndex - b.declarationIndex;
}
function compareResults(a, b) {
    return compareTests(a.test, b.test) || a.target.index - b.target.index;
}
/** Report order is completion-time independent. */
function compareSerialGroups(a, b, targetIndex) {
    if (a.file !== b.file)
        return a.file < b.file ? -1 : 1;
    if (a.declarationIndex !== b.declarationIndex)
        return a.declarationIndex - b.declarationIndex;
    return (targetIndex.get(a.targetId) ?? 0) - (targetIndex.get(b.targetId) ?? 0);
}
